public class Perf {
    static String plus(int n) {
        String s = "";
        for (int i = 0; i < n; i++) s += "x";
        return s;
    }
    static String sb(int n) {
        StringBuilder b = new StringBuilder();
        for (int i = 0; i < n; i++) b.append('x');
        return b.toString();
    }
    public static void main(String[] args) {
        for (int w = 0; w < 3; w++) { plus(2000); sb(2000); }   // warm up the JIT
        for (int n : new int[]{10_000, 50_000, 100_000}) {
            long t0 = System.nanoTime(); plus(n);
            long t1 = System.nanoTime(); sb(n);
            long t2 = System.nanoTime();
            System.out.printf("n=%,d  +=: %d ms   StringBuilder: %d ms%n",
                              n, (t1 - t0) / 1_000_000, (t2 - t1) / 1_000_000);
        }
    }
}

