import java.util.regex.*;

public class Rx {
    public static void main(String[] args) {
        Pattern p = Pattern.compile("(?<year>\\d{4})-(?<month>\\d{2})-(?<day>\\d{2})");
        Matcher m = p.matcher("Due 2026-10-09, paid 2026-10-12.");
        while (m.find()) {
            System.out.println(m.group() + " year=" + m.group("year")
                + " month=" + m.group(2) + " at " + m.start() + "-" + m.end());
        }
        System.out.println(Pattern.matches("\\d+", "123abc") + " "
            + Pattern.compile("\\d+").matcher("123abc").lookingAt());
        String html = "<b>bold</b> and <i>italic</i>";
        System.out.println(html.replaceAll("<.+>", "#"));
        System.out.println(html.replaceAll("<.+?>", "#"));
        System.out.println("John Smith".replaceAll("(\\w+) (\\w+)", "$2, $1"));
        System.out.println(Pattern.compile("\\d+").matcher("a1b22c333")
            .replaceAll(r -> "<" + r.group().length() + ">"));
        System.out.println(Pattern.compile("[,;]\\s*").splitAsStream("a, b;c").toList());
        System.out.println("a.b".replace(".", "-") + " " + "a.b".replaceAll(".", "-")
            + " " + Pattern.quote("a.b"));
        Matcher e = Pattern.compile("(a)(b)?").matcher("a");
        e.matches();
        System.out.println(e.groupCount() + " " + e.group(2));
    }
}

import java.util.regex.Pattern;

public class Backtrack {
    static long ms(String regex, String input) {
        long t0 = System.nanoTime();
        Pattern.compile(regex).matcher(input).matches();
        return (System.nanoTime() - t0) / 1_000_000;
    }
    public static void main(String[] args) {
        for (int n = 14; n <= 22; n += 2) {
            String bad = "(a?)".repeat(n) + "a".repeat(n);   // (a?)(a?)...aaa
            String good = "a{" + n + "}";                      // same language
            String input = "a".repeat(n);
            System.out.printf("n=%d  nested optionals: %d ms   a{n}: %d ms%n",
                              n, ms(bad, input), ms(good, input));
        }
    }
}

