import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.text.Normalizer;
import java.util.HexFormat;

public class Uni {
    public static void main(String[] args) {
        String s = "A\u00e9\u20ac\uD83D\uDE00";   // A, e-acute, euro sign, grinning face
        System.out.println("length()       = " + s.length());
        System.out.println("codePointCount = " + s.codePointCount(0, s.length()));
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            System.out.printf("char %d: U+%04X  surrogate=%b%n",
                i, (int) c, Character.isSurrogate(c));
        }
        s.codePoints().forEach(cp -> System.out.printf("cp U+%X  %s%n", cp, Character.getName(cp)));

        for (Charset cs : new Charset[] {StandardCharsets.ISO_8859_1, StandardCharsets.UTF_8,
                                         StandardCharsets.UTF_16BE, StandardCharsets.UTF_16}) {
            byte[] b = s.getBytes(cs);
            System.out.println(cs + " -> " + b.length + " bytes " + HexFormat.of().formatHex(b));
        }

        byte[] utf8 = "caf\u00e9".getBytes(StandardCharsets.UTF_8);       // 5 bytes
        String wrong = new String(utf8, StandardCharsets.ISO_8859_1);     // mojibake
        System.out.println(utf8.length + " bytes, wrong decode has " + wrong.length() + " chars, "
            + "right decode equals original: "
            + new String(utf8, StandardCharsets.UTF_8).equals("caf\u00e9"));

        String n1 = "\u00e9", n2 = "e\u0301";   // precomposed vs e + combining acute
        System.out.println(n1.equals(n2) + " " + n1.length() + " " + n2.length() + " "
            + Normalizer.normalize(n2, Normalizer.Form.NFC).equals(n1));
        System.out.println("default charset = " + Charset.defaultCharset());
    }
}

import java.text.Collator;
import java.text.NumberFormat;
import java.text.ParseException;
import java.util.*;

public class Loc {
    // show every non-ASCII char as \\uXXXX so the output is unambiguous
    static String esc(String s) {
        StringBuilder b = new StringBuilder();
        for (char c : s.toCharArray()) {
            b.append(c < 128 ? String.valueOf(c) : String.format("\\u%04x", (int) c));
        }
        return b.toString();
    }
    public static void main(String[] args) throws ParseException {
        Locale tr = Locale.forLanguageTag("tr");
        System.out.println(esc("TITLE".toLowerCase(tr)) + " " + esc("title".toUpperCase(tr)));
        System.out.println("TITLE".toLowerCase(Locale.ROOT) + " "
            + "title".toUpperCase(Locale.ROOT));
        System.out.println("stra\u00dfe".toUpperCase(Locale.ROOT));

        double v = 1234567.891;
        for (Locale l : List.of(Locale.US, Locale.GERMANY, Locale.forLanguageTag("en-IN"))) {
            String num = NumberFormat.getNumberInstance(l).format(v);
            String cur = NumberFormat.getCurrencyInstance(l).format(v);
            System.out.println(l.toLanguageTag() + "  " + esc(num) + "  " + esc(cur));
        }
        NumberFormat de = NumberFormat.getInstance(Locale.GERMANY);
        System.out.println(de.parse("1.234,5") + " " + Double.parseDouble("1234.5")
            + " " + de.parse("12abc"));

        List<String> w = new ArrayList<>(List.of("zebra", "\u00e4pfel", "apple", "Zoo"));
        Collections.sort(w);
        System.out.println(esc(w.toString()));
        w.sort(Collator.getInstance(Locale.GERMANY));
        System.out.println(esc(w.toString()));
    }
}

