import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;

public class Bd {
    public static void main(String[] args) {
        System.out.println(0.1 + 0.2);
        BigDecimal x = new BigDecimal("0.1").add(new BigDecimal("0.2"));
        System.out.println(x);
        System.out.println(new BigDecimal(0.1));
        System.out.println(BigDecimal.valueOf(0.1));

        BigDecimal a = new BigDecimal("2.0");
        BigDecimal b = new BigDecimal("2.00");
        System.out.println(a.equals(b) + " " + a.compareTo(b) + " " + a.hashCode()
            + " " + b.hashCode());
        System.out.println("scale=" + b.scale() + " precision=" + b.precision()
            + " unscaled=" + b.unscaledValue());

        BigDecimal price = new BigDecimal("19.99");
        BigDecimal qty = new BigDecimal("3");
        BigDecimal total = price.multiply(qty);
        System.out.println(total + " scale " + total.scale());
        BigDecimal rate = new BigDecimal("0.075");
        BigDecimal tax = total.multiply(rate);
        System.out.println(tax + " -> " + tax.setScale(2, RoundingMode.HALF_UP));

        try {
            BigDecimal.ONE.divide(new BigDecimal("3"));
        } catch (ArithmeticException e) {
            System.out.println(e.getMessage());
        }
        System.out.println(BigDecimal.ONE.divide(new BigDecimal("3"), 5, RoundingMode.HALF_EVEN));
        System.out.println(BigDecimal.ONE.divide(new BigDecimal("3"), MathContext.DECIMAL32));
        System.out.println(new BigDecimal("1.10").stripTrailingZeros() + " "
            + new BigDecimal("100").stripTrailingZeros() + " "
            + new BigDecimal("100").stripTrailingZeros().toPlainString());
    }
}

import java.math.BigDecimal;
import java.math.RoundingMode;

public class Rm {
    public static void main(String[] args) {
        String[] inputs = {"5.5", "2.5", "1.6", "1.1", "-1.1", "-1.6", "-2.5"};
        System.out.printf("%-10s", "mode");
        for (String s : inputs) System.out.printf("%5s", s);
        System.out.println();
        for (RoundingMode m : RoundingMode.values()) {
            if (m == RoundingMode.UNNECESSARY) continue;
            System.out.printf("%-10s", m);
            for (String s : inputs) {
                System.out.printf("%5s", new BigDecimal(s).setScale(0, m));
            }
            System.out.println();
        }
    }
}

import java.math.BigInteger;

public class Bi {
    static BigInteger fact(int n) {
        BigInteger r = BigInteger.ONE;
        for (int i = 2; i <= n; i++) r = r.multiply(BigInteger.valueOf(i));
        return r;
    }
    public static void main(String[] args) {
        System.out.println(fact(25));
        System.out.println(fact(25).bitLength() + " bits, "
            + fact(100).toString().length() + " digits in 100!");
        BigInteger p = BigInteger.TWO.pow(127).subtract(BigInteger.ONE);
        System.out.println(p + " prime? " + p.isProbablePrime(50));
        System.out.println(BigInteger.valueOf(48).gcd(BigInteger.valueOf(180)));
        try {
            BigInteger.valueOf(Long.MAX_VALUE).add(BigInteger.ONE).longValueExact();
        } catch (ArithmeticException e) {
            System.out.println(e.getMessage());
        }
        System.out.println(Long.MAX_VALUE + 1);
    }
}

