            + d.with(TemporalAdjusters.next(DayOfWeek.MONDAY)));
        LocalDateTime ldt = LocalDateTime.of(d, LocalTime.of(9, 30));
        System.out.println(ldt + " " + LocalTime.of(9, 30, 15));
        try {
            LocalDate.of(2023, 2, 29);
        } catch (DateTimeException e) {
            System.out.println(e.getMessage());
        }
        Instant i = Instant.ofEpochSecond(1_700_000_000L);
        System.out.println(i + " " + i.toEpochMilli());
        ZonedDateTime ny = i.atZone(ZoneId.of("America/New_York"));
        ZonedDateTime kol = i.atZone(ZoneId.of("Asia/Kolkata"));
        System.out.println(ny + "\n" + kol);
        System.out.println(ny.toInstant().equals(kol.toInstant()) + " " + ny.toOffsetDateTime());

        Period p = Period.between(LocalDate.of(2020, 2, 29), LocalDate.of(2024, 3, 15));
        Duration du = Duration.between(LocalTime.of(8, 15), LocalTime.of(17, 45, 30));
        System.out.println(p + " " + p.getYears() + "y " + p.getMonths() + "m "
            + p.getDays() + "d");
        System.out.println(du + " " + du.toMinutes() + " min " + du.toHoursPart() + "h"
            + du.toMinutesPart() + "m");
        System.out.println(ChronoUnit.DAYS.between(
            LocalDate.of(2024, 1, 1), LocalDate.of(2025, 1, 1)));
    }
}

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.util.Locale;

public class DateFmt {
    public static void main(String[] args) {
        LocalDateTime ldt = LocalDateTime.of(2024, 1, 31, 9, 30);
        DateTimeFormatter f = DateTimeFormatter.ofPattern("dd MMM yyyy, HH:mm", Locale.ENGLISH);
        System.out.println(ldt.format(f) + " | " + DateTimeFormatter.ISO_LOCAL_DATE.format(ldt));
        DateTimeFormatter smart = DateTimeFormatter.ofPattern("dd/MM/uuuu");
        System.out.println(LocalDate.parse("15/08/2025", smart));
        System.out.println(LocalDate.parse("31/04/2025", smart));
        DateTimeFormatter strict = smart.withResolverStyle(ResolverStyle.STRICT);
        try {
            LocalDate.parse("31/04/2025", strict);
        } catch (DateTimeParseException e) {
            System.out.println(e.getMessage());
        }
        DateTimeFormatter strictY = DateTimeFormatter.ofPattern("dd/MM/yyyy")
            .withResolverStyle(ResolverStyle.STRICT);
        try {
            LocalDate.parse("15/08/2025", strictY);
        } catch (DateTimeParseException e) {
            System.out.println(e.getMessage());
        }
    }
}

import java.time.Duration;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.temporal.ChronoUnit;

public class Dst {
    public static void main(String[] args) {
        ZoneId ny = ZoneId.of("America/New_York");
        ZonedDateTime before = ZonedDateTime.of(2024, 3, 9, 12, 0, 0, 0, ny);
        System.out.println("plusDays(1)  : " + before.plusDays(1));
        System.out.println("plusHours(24): " + before.plusHours(24));
        System.out.println("hours between: "
            + ChronoUnit.HOURS.between(before, before.plusDays(1)));
        ZonedDateTime gap = ZonedDateTime.of(LocalDateTime.of(2024, 3, 10, 2, 30), ny);
        System.out.println("gap  : " + gap);
        LocalDateTime amb = LocalDateTime.of(2024, 11, 3, 1, 30);
        ZonedDateTime first = ZonedDateTime.of(amb, ny);
        System.out.println("overlap first : " + first);
        System.out.println("overlap second: " + first.withLaterOffsetAtOverlap());
        System.out.println("day length: " + Duration.between(
            LocalDate.of(2024, 11, 3).atStartOfDay(ny),
            LocalDate.of(2024, 11, 4).atStartOfDay(ny)));
    }
}

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;

public class Svc {
    record Token(String value, Instant expires) {}

    static class TokenService {
        private final Clock clock;
        TokenService(Clock clock) { this.clock = clock; }
        Token issue(String v) { return new Token(v, clock.instant().plus(Duration.ofMinutes(30))); }
        boolean isValid(Token t) { return clock.instant().isBefore(t.expires()); }
    }

    static class MutableClock extends Clock {
        private Instant now;
        MutableClock(Instant start) { this.now = start; }
        void advance(Duration d) { now = now.plus(d); }
        @Override public ZoneId getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(ZoneId z) { return this; }
        @Override public Instant instant() { return now; }
    }

    public static void main(String[] args) {
        MutableClock clock = new MutableClock(Instant.parse("2025-01-01T10:00:00Z"));
        TokenService svc = new TokenService(clock);
        Token t = svc.issue("abc");
        System.out.println(t);
        System.out.println("valid now: " + svc.isValid(t));
        clock.advance(Duration.ofMinutes(29));
        System.out.println("valid after 29 min: " + svc.isValid(t));
        clock.advance(Duration.ofMinutes(2));
        System.out.println("valid after 31 min: " + svc.isValid(t));
    }
}

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.temporal.TemporalAdjusters;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

public class Bill {
    static final Set<DayOfWeek> WEEKEND = Set.of(DayOfWeek.SATURDAY, DayOfWeek.SUNDAY);

    static LocalDate nextBusinessDay(LocalDate d) {
        LocalDate r = d;
        while (WEEKEND.contains(r.getDayOfWeek())) r = r.plusDays(1);
        return r;
    }
    public static void main(String[] args) {
        LocalDate start = LocalDate.of(2025, 1, 31);
        List<LocalDate> due = new ArrayList<>();
        for (int i = 0; i < 4; i++) due.add(nextBusinessDay(start.plusMonths(i)));
        System.out.println(due);
        // wrong: repeated plusMonths(1) drifts
        LocalDate d = start;
        for (int i = 0; i < 3; i++) d = d.plusMonths(1);
        System.out.println("iterated: " + d + "  direct: " + start.plusMonths(3));
        YearMonth ym = YearMonth.of(2025, 2);
        System.out.println(ym + " " + ym.lengthOfMonth() + " " + ym.atEndOfMonth()
            + " " + ym.atDay(1).getDayOfWeek());
        System.out.println(LocalDate.of(2025, 11, 1)
            .with(TemporalAdjusters.dayOfWeekInMonth(4, DayOfWeek.THURSDAY)));
        LocalDate birthday = LocalDate.of(2000, 2, 29);
        System.out.println(java.time.Period.between(birthday, LocalDate.of(2025, 2, 28)).getYears()
            + " " + java.time.Period.between(birthday, LocalDate.of(2025, 3, 1)).getYears());
    }
}
